import "server-only";
import { CATEGORIES } from "../domain/categories";
import type { Mission, NetworkSnapshot } from "../domain/types";
import type { AnalysisResult } from "../engine/analysis";
import type { AppState, Device, OpsNotification } from "../store/appStore";
import { newId } from "./pin";

/**
 * Important operational alerts, generated by OUR backend after each analysis.
 * Rules are deliberately strict — no alert for every small recommendation:
 *  • only core categories, only open fridges with real demand (≥ 2 expected in 2 h)
 *  • stock runs out within ALERT_MINUTES
 *  • the same fridge × category is not repeated within DEDUPE_MINUTES
 *  • at most MAX_PER_RUN alerts per analysis
 * Delivery goes through NotificationSender. Today: log + in-app banner. Later: FCM push (Android).
 */

const ALERT_MINUTES = 45;
const DEDUPE_MINUTES = 120;
const MAX_PER_RUN = 3;

const CAT_NOM: Record<string, string> = {
  breakfast: "завтраки", hot: "горячие блюда", salad: "салаты", snack: "перекусы", dessert: "десерты", drink: "напитки",
};

const CAT_GEN: Record<string, string> = {
  breakfast: "завтраков", hot: "горячих блюд", salad: "салатов", snack: "перекусов", dessert: "десертов", drink: "напитков",
};

export interface NotificationSender {
  readonly channel: string;
  isConfigured(): boolean;
  send(n: OpsNotification, devices: Device[]): Promise<void>;
}

/** Default channel: server log. The app also shows recent alerts as an in-app banner. */
export class LogSender implements NotificationSender {
  readonly channel = "log";
  isConfigured() {
    return true;
  }
  async send(n: OpsNotification) {
    console.info(`[alert] ${n.title} — ${n.body}`);
  }
}

/**
 * Registry of channels. To add Android push later: implement FcmSender (firebase-admin, service account
 * from env FCM_SERVICE_ACCOUNT_JSON), register it here, add @capacitor/push-notifications to the app.
 * See docs/ANDROID.md → "Push notifications".
 */
export const senders: NotificationSender[] = [new LogSender()];

export function detectAlerts(snap: NetworkSnapshot, a: AnalysisResult, state: AppState, missions: Mission[]): OpsNotification[] {
  const out: OpsNotification[] = [];
  const recent = new Map(state.notifications.map((n) => [n.key, n.at]));
  const candidates = a.forecasts
    .filter((ff) => ff.isOpenNow)
    .flatMap((ff) =>
      ff.categories
        .filter((c) => CATEGORIES[c.categoryIndex].core && c.expected2h >= 2 && c.minutesToEmpty !== null && c.minutesToEmpty <= ALERT_MINUTES)
        .map((c) => ({ ff, c })),
    )
    .sort((x, y) => (x.c.minutesToEmpty ?? 0) - (y.c.minutesToEmpty ?? 0));

  for (const { ff, c } of candidates) {
    if (out.length >= MAX_PER_RUN) break;
    const fr = snap.fridges[ff.fridgeIndex];
    const cat = CATEGORIES[c.categoryIndex];
    const key = `${fr.id}:${cat.id}`;
    const last = recent.get(key);
    if (last !== undefined && snap.now - last < DEDUPE_MINUTES * 60_000) continue;
    const mission = missions.find((m) => m.status === "NEW" && m.lines.some((l) => l.targetFridgeId === fr.id && l.categoryId === cat.id));
    const minutes = c.minutesToEmpty ?? 0;
    out.push({
      id: newId("N"),
      at: snap.now,
      key,
      level: minutes <= 20 ? "critical" : "warning",
      title: minutes === 0 ? `🔴 ${fr.name}: закончились ${CAT_NOM[cat.id]}` : `🔴 ${fr.name} может остаться без ${CAT_GEN[cat.id]} через ${minutes} мин`,
      body: mission ? `Задача #${mission.number} уже в очереди.` : "Проверьте остатки.",
      fridgeId: fr.id,
      missionId: mission?.id ?? null,
      delivered: {},
    });
  }
  return out;
}

export async function deliver(n: OpsNotification, devices: Device[]): Promise<void> {
  for (const s of senders) {
    if (!s.isConfigured()) continue;
    try {
      await s.send(n, devices);
      n.delivered[s.channel] = Date.now();
    } catch (e) {
      console.error(`[alert] channel ${s.channel} failed`, e);
    }
  }
}
